import "server-only";
import { db } from "@/lib/db";

export async function readSendingActive(userId: string): Promise<boolean> {
  const send = await db.send.findFirst({
    where: {
      campaign: { userId },
      status: "QUEUED",
      deliveryState: { not: "UNCERTAIN" },
    },
    select: { id: true },
  });
  return send !== null;
}
